/* Offline tutorial; the PDF is bundled and embedded during synchronization. */
(()=>{'use strict';const $=id=>document.getElementById(id);let url;
function pdfURL(){if(!url){const data=JSON.parse($('kp-user-tutorial-pdf').textContent),raw=atob(data.base64);url=URL.createObjectURL(new Blob([Uint8Array.from(raw,c=>c.charCodeAt(0))],{type:'application/pdf'}));}return url;}
function language(){const mr=window.KPPreferences?.get().language==='marathi';for(const n of document.querySelectorAll('[data-guide-en]'))n.textContent=mr?n.dataset.guideMr:n.dataset.guideEn;}
function init(){const box=$('help-tutorial-content');box.dataset.noLocalize='true';box.innerHTML='<h2 data-guide-en="Software tutorial" data-guide-mr="सॉफ्टवेअर वापर मार्गदर्शक">Software tutorial</h2><p data-guide-en="12-page A4 PDF tutorial in English. Covers charts, predictions, Ruling Planets, transit searches, settings, printing and backups. Available offline." data-guide-mr="इंग्रजीतील १२ पानी ए४ पीडीएफ मार्गदर्शक. कुंडली, भविष्य, शासक ग्रह, गोचर शोध, सेटिंग, प्रिंट व बॅकअप यांचा समावेश. ऑफलाइन उपलब्ध."></p><div class="help-pdf-actions"><button type="button" id="help-view-pdf" data-guide-en="View tutorial PDF" data-guide-mr="मार्गदर्शक पीडीएफ पहा"></button><a id="help-open-pdf" target="_blank" rel="noopener" data-guide-en="Open PDF in new tab" data-guide-mr="पीडीएफ नव्या टॅबमध्ये उघडा"></a><a id="help-download-pdf" download="KP-MASTER-User-Tutorial-1.2.9.pdf" data-guide-en="Download PDF" data-guide-mr="पीडीएफ डाउनलोड करा"></a></div><p data-guide-en="If the embedded PDF viewer is unavailable, use Open PDF or Download PDF." data-guide-mr="पीडीएफ येथे दिसत नसल्यास नव्या टॅबमध्ये उघडा किंवा डाउनलोड करा."></p><iframe id="help-tutorial-viewer" title="KP MASTER software tutorial PDF" hidden></iframe>';
for(const id of ['help-open-pdf','help-download-pdf'])$(id).href=pdfURL();$('help-view-pdf').onclick=()=>{const viewer=$('help-tutorial-viewer');viewer.src=pdfURL()+'#toolbar=1&view=FitH';viewer.hidden=false;};const quick=document.createElement('button');quick.type='button';quick.dataset.guideEn='Software tutorial PDF';quick.dataset.guideMr='सॉफ्टवेअर मार्गदर्शक पीडीएफ';quick.onclick=()=>{$('workspace-help').close();document.querySelector('.app-sidebar [data-tab="help"]')?.click();};$('workspace-help').append(quick);language();window.addEventListener('kp-preferences-changed',language);}
window.KPUserTutorial=Object.freeze({pdfURL});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();
